int main(){try{Context context;GLuint fbo=0,tex=0;glGenFramebuffers(1,&fbo);glBindFramebuffer(GL_FRAMEBUFFER,fbo);GLenum bad=glCheckFramebufferStatus(GL_FRAMEBUFFER);require(bad==GL_FRAMEBUFFER_INCOMPLETE_MISSING_ATTACHMENT,"missing attachment fixture not reproduced");glGenTextures(1,&tex);glBindTexture(GL_TEXTURE_2D,tex);glTexStorage2D(GL_TEXTURE_2D,1,GL_RGBA8,16,16);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,tex,0);GLenum good=glCheckFramebufferStatus(GL_FRAMEBUFFER);require(good==GL_FRAMEBUFFER_COMPLETE,"patched fixture incomplete");glViewport(0,0,16,16);glClearColor(0.25f,0.5f,0.75f,1);glClear(GL_COLOR_BUFFER_BIT);std::array<unsigned char,4>pixel{};glReadPixels(0,0,1,1,GL_RGBA,GL_UNSIGNED_BYTE,pixel.data());require(pixel[0]>=63&&pixel[0]<=64&&pixel[1]>=127&&pixel[1]<=128&&pixel[2]>=191&&pixel[2]<=192&&pixel[3]==255,"patched pixel");GLint draw=0,read=0,programName=0,viewport[4]{};glGetIntegerv(GL_DRAW_FRAMEBUFFER_BINDING,&draw);glGetIntegerv(GL_READ_FRAMEBUFFER_BINDING,&read);glGetIntegerv(GL_CURRENT_PROGRAM,&programName);glGetIntegerv(GL_VIEWPORT,viewport);check("snapshot");std::cout<<"{\"schema_version\":1,\"status\":\"PASS\",\"vendor\":"<<quote(reinterpret_cast<const char*>(glGetString(GL_VENDOR)))<<",\"renderer\":"<<quote(reinterpret_cast<const char*>(glGetString(GL_RENDERER)))<<",\"version\":"<<quote(reinterpret_cast<const char*>(glGetString(GL_VERSION)))<<",\"before_fbo_status\":"<<bad<<",\"after_fbo_status\":"<<good<<",\"draw_fbo\":"<<draw<<",\"read_fbo\":"<<read<<",\"program\":"<<programName<<",\"viewport\":["<<viewport[0]<<','<<viewport[1]<<','<<viewport[2]<<','<<viewport[3]<<"],\"readback_rgba\":["<<unsigned(pixel[0])<<','<<unsigned(pixel[1])<<','<<unsigned(pixel[2])<<','<<unsigned(pixel[3])<<"],\"protected\":false,\"driver_defect_claim\":false}\n";glBindFramebuffer(GL_FRAMEBUFFER,0);glDeleteFramebuffers(1,&fbo);glDeleteTextures(1,&tex);return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
